#include <stdio.h>

/* 砍一半：两头夹着找，每趟看正中间那一只，答「比了几次」；没找到答负数 */
int half_find(int a[], int n, int target) {
    int lo = 0;
    int hi = n - 1;
    int tries = 0;

    while (lo <= hi) {
        int mid = (lo + hi) / 2;
        tries++;
        if (a[mid] == target) {
            return tries;
        } else if (a[mid] < target) {
            lo = mid + 1;
        } else {
            hi = mid - 1;
        }
    }
    return -tries;
}

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) {
        return 1;
    }
    int target;
    if (scanf("%d", &target) != 1) {
        return 1;
    }
    int a[64];
    for (int i = 0; i < n; i++) {
        if (scanf("%d", &a[i]) != 1) {
            return 1;
        }
    }

    int times = half_find(a, n, target);
    if (times < 0) {
        printf("砍一半：没找到\n");
    } else {
        printf("砍一半：比了 %d 次\n", times);
    }
    return 0;
}
